-- 取一个待办并标记为处理中，两步必须在同一事务内
BEGIN IMMEDIATE;
UPDATE queue SET state = 'running' WHERE id = (
    SELECT id FROM queue WHERE state = 'pending' ORDER BY id LIMIT 1
);
COMMIT;

SELECT id, job, state FROM queue ORDER BY id;

